#include "../src/transport.hpp"
#include <iostream>
vpn::Bytes decode_hex(const std::string& s){vpn::Bytes b;if(s.size()%2)throw std::runtime_error("hex");for(size_t i=0;i<s.size();i+=2){int a=vpn::hex_digit(s[i]),c=vpn::hex_digit(s[i+1]);if(a<0||c<0)throw std::runtime_error("hex");b.push_back(uint8_t(a*16+c));}return b;}
vpn::Json socket_probe(const vpn::Json& j){[[maybe_unused]] vpn::NetworkRuntime runtime;vpn::Config c;c.server="127.0.0.1";c.port=uint16_t(vpn::number(j.at("port").scalar(),1,65535));c.finalmask=j.at("fm");auto deadline=vpn::Clock::now()+std::chrono::seconds(10);auto s=vpn::connect_server(c,deadline);int size=1024;if(setsockopt(s.get(),SOL_SOCKET,SO_SNDBUF,reinterpret_cast<char*>(&size),sizeof(size)))throw std::runtime_error("send buffer");auto b=decode_hex(j.at("data").scalar());size_t pos=0,retries=0;while(pos<b.size()){s.write_deadline(deadline);int n=s.send(b.data()+pos,b.size()-pos);if(n==-2){++retries;vpn::wait_socket(s.get(),true,deadline);}else pos+=size_t(n);}vpn::Json out=vpn::Json::obj();out["bytes"]=vpn::Json::integer(pos);out["partial_retries"]=vpn::Json::integer(retries);return out;}
int main(){std::string line;while(std::getline(std::cin,line)){try{auto j=vpn::json_parse(line);if(j.at("op").scalar()=="socket"){std::cout<<vpn::json_dump(socket_probe(j))<<'\n';continue;}vpn::Json output=vpn::Json::arr();if(j.at("op").scalar()=="http"){vpn::HttpBody body;vpn::Bytes data;for(const auto& p:j.at("parts").array){auto b=decode_hex(p.scalar());auto plain=body.feed(b);data.insert(data.end(),plain.begin(),plain.end());}vpn::Json r=vpn::Json::obj();r["data"]=vpn::Json(vpn::hex_bytes(data));r["closed"]=vpn::Json::boolean(body.closed());std::cout<<vpn::json_dump(r)<<'\n';continue;}vpn::Config c;c.finalmask=j.at("fm");vpn::FragmentMask mask(c);for(const auto& p:j.at("parts").array){auto b=decode_hex(p.scalar());auto chunks=mask.write(b.data(),b.size());vpn::Json write=vpn::Json::arr();for(const auto& chunk:chunks){vpn::Json r=vpn::Json::obj();r["data"]=vpn::Json(vpn::hex_bytes(chunk.bytes));r["delay_ms"]=vpn::Json::integer(chunk.delay_after_ms);write.array.push_back(r);}output.array.push_back(write);}std::cout<<vpn::json_dump(output)<<'\n';}catch(const std::exception& e){vpn::Json out=vpn::Json::obj();out["error"]=vpn::Json(e.what());std::cout<<vpn::json_dump(out)<<'\n';}}}
